'use strict';

// MODULES //

var isnan = require( '@stdlib/math-base-assert-is-nan' );
var sin = require( '@stdlib/math-base-special-sin' );
var PI = require( '@stdlib/constants-float64-pi' );


// MAIN //

/**
* Returns the variance of a log-logistic distribution with scale parameter `alpha` and shape parameter `beta`.
*
* @param {PositiveNumber} alpha - scale parameter
* @param {PositiveNumber} beta - shape parameter
* @returns {PositiveNumber} variance
*
* @example
* var y = variance( 1.0, 3.0 );
* // returns ~0.956
*
* @example
* var y = variance( 4.0, 3.0 );
* // returns ~15.300
*
* @example
* var y = variance( 1.0, 2.0 );
* // returns NaN
*
* @example
* var y = variance( NaN, 3.0 );
* // returns NaN
*
* @example
* var y = variance( 2.0, NaN );
* // returns NaN
*
* @example
* var y = variance( -1.0, 3.0 );
* // returns NaN
*
* @example
* var y = variance( 2.0, -1.0 );
* // returns NaN
*/
function variance( alpha, beta ) {
	var b2;
	var b;
	var s;
	if (
		isnan( alpha ) ||
		isnan( beta ) ||
		alpha <= 0.0 ||
		beta <= 2.0
	) {
		return NaN;
	}
	b = PI / beta;
	b2 = 2.0 * b;
	s = sin( b );
	return ( alpha * alpha ) * ( ( b2 / sin( b2 ) ) - ( ( b * b ) / ( s * s ) ) );
}


// EXPORTS //

module.exports = variance;
